import json
import os
import shutil


def layout(path):
    # One row per status: the table's data files, their rows, and the rows in the largest file. Don't change this.
    files = {}
    log = path + "/_delta_log/"
    for name in sorted(f for f in os.listdir(log) if f.endswith(".json")):
        with open(log + name) as f:
            for line in f:
                action = json.loads(line)
                if "add" in action:
                    add = action["add"]
                    files[add["path"]] = (add["partitionValues"].get("status"), json.loads(add["stats"])["numRecords"])
                if "remove" in action:
                    files.pop(action["remove"]["path"], None)
    by_status = {}
    for status, rows in files.values():
        by_status.setdefault(status, []).append(rows)
    return spark.createDataFrame(
        [(status, len(rows), sum(rows), max(rows)) for status, rows in by_status.items()],
        "status STRING, files INT, rows INT, largest INT",
    )


def write_table(invoices, path):
    # Partition by status, at most 4 invoices per file, as few files as possible.
    invoices.write.format("delta").partitionBy("status").save(path)


def solve(invoices):
    path = "/tmp/billing/invoices"
    shutil.rmtree(path, ignore_errors=True)  # start from an empty folder on every run
    feed = invoices.repartition(4)  # the feed hands the invoices over in four partitions
    write_table(feed, path)
    return layout(path)
